const body = $('Admin API Webhook').first().json.body || {};
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
return [{ json: {
  action: str(body.action),
  sessionId: str(body.sessionId),
  startDate: str(body.startDate),          // ISO 8601 з часовою зоною (бекенд адмінпанелі надсилає UTC)
  maxParticipants: body.maxParticipants,
  pipelineId: body.pipelineId,             // ID воронки з довідника PIPELINES
  responsibleIds: body.responsibleIds === undefined ? null : body.responsibleIds, // масив ID співробітників; null — не передано
  cardId: str(body.cardId),                // ID картки KeyCRM (ручний запис кандидата)
} }];

const cfg = $('Конфіг').first().json;
const rows = (items) => items.map((i) => i.json).filter((j) => j && j.id !== undefined && j.id !== null);
const maxOf = (s) => (Number(s.max_participants) > 0 ? Number(s.max_participants) : Number(cfg.DEFAULT_MAX_PARTICIPANTS));
const shapeSession = (s, count) => {
  const max = maxOf(s);
  return {
    id: s.session_id,
    name: s.session_name || '',
    startDate: s.start_date || null,                         // ISO 8601 UTC
    status: s.status || 'Open',                              // Open / Full / Closed
    pipelineId: pipelineId(s.pipeline_id),                   // воронка KeyCRM
    pipelineName: s.pipeline_name || '',
    responsibleIds: parseIds(s.responsible_ids),            // ID співробітників (KeyCRM) з таблиці Interview Responsibles
    responsibles: parseIds(s.responsible_ids).map(responsibleView),
    maxParticipants: max,
    currentCount: count,                                     // активні (не Cancelled) реєстрації
    availableSeats: Math.max(0, max - count),
    isPast: s.start_date ? new Date(s.start_date).getTime() <= Date.now() : false,
    createdAt: s.createdAt || null,
    updatedAt: s.updatedAt || null,
  };
};
const shapeParticipant = (p) => ({
  id: p.id,
  name: p.name || '',
  phone: p.phone || '',
  keycrmId: p.keycrm_id || '',
  registrationStatus: p.registration_status || '',
  keycrmSync: p.keycrm_sync || '',
  createdAt: p.createdAt || null,
});
// Довідник воронок: JSON-масив [{ id, name }] у полі PIPELINES вузла «Конфіг»
let PIPELINES;
try {
  PIPELINES = JSON.parse(cfg.PIPELINES || '[]');
  if (!Array.isArray(PIPELINES)) throw new Error('not an array');
} catch (e) {
  throw new Error('Конфіг: PIPELINES має бути JSON-масивом [{ "id": 1, "name": "…" }]');
}
const pipelineId = (v) => (v === null || v === undefined || v === '' || !Number.isInteger(Number(v)) ? null : Number(v));
const pipelineById = (id) => PIPELINES.find((p) => pipelineId(p.id) === id);
// Відповідальні: таблиця Interview Responsibles (employee_id, name, discord_id). Якщо таблиці ще немає — довідник порожній.
const respRead = $('DT: відповідальні').all().map((i) => i.json);
const respErr = respRead.find((j) => j && j.error);
const RESPONSIBLES_ERROR = respErr ? String(respErr.error.message || respErr.error) : '';
const RESPONSIBLES = rows($('DT: відповідальні').all())
  .map((r) => ({ id: Number(r.employee_id), name: String(r.name || '').trim(), discordId: r.discord_id === null || r.discord_id === undefined ? '' : String(r.discord_id).trim() }))
  .filter((r) => Number.isInteger(r.id) && r.id > 0 && r.name)
  .sort((a, b) => a.name.localeCompare(b.name, 'uk'));
const responsibleById = (id) => RESPONSIBLES.find((r) => r.id === id);
// Зберігається в сесії рядком «13,39»
const parseIds = (v) => [...new Set(String(v === null || v === undefined ? '' : v).split(/[^0-9]+/).filter(Boolean).map(Number).filter((n) => Number.isInteger(n) && n > 0))];
const responsibleView = (id) => {
  const r = responsibleById(id);
  return r ? { id, name: r.name, discordLinked: !!r.discordId } : { id, name: 'Співробітник #' + id, discordLinked: false, missing: true };
};
// responsibleIds із запиту: undefined — не передано; інакше масив цілих ID. allowed — ID, які вже є в сесії (можуть бути відсутні в довіднику)
const checkResponsibles = (raw, allowed = []) => {
  if (raw === undefined || raw === null) return { ids: undefined };
  if (!Array.isArray(raw)) return { error: fail(400, 'INVALID_RESPONSIBLES', 'responsibleIds має бути масивом') };
  const ids = [...new Set(raw.map(Number))];
  if (ids.some((n) => !Number.isInteger(n) || n <= 0)) return { error: fail(400, 'INVALID_RESPONSIBLES', 'Некоректний ID відповідального') };
  const unknown = ids.filter((id) => !responsibleById(id) && !allowed.includes(id));
  if (unknown.length) return { error: fail(400, 'UNKNOWN_RESPONSIBLE', 'Співробітника не знайдено в таблиці Interview Responsibles: ' + unknown.join(', '), { unknown }) };
  return { ids };
};
const isActive = (p) => p.registration_status !== 'Cancelled';
const fail = (statusCode, code, message, extra = {}) => ({ json: { ok: false, statusCode, body: { error: { code, message, ...extra } } } });
const ok = (statusCode, body) => ({ json: { ok: true, statusCode, body } });
