const sessionName = (iso, pipelineName) => 'Групова співбесіда — ' + (pipelineName ? pipelineName + ' — ' : '') + DateTime.fromISO(iso, { zone: 'utc' }).setZone(cfg.TIMEZONE).setLocale('uk').toFormat('d MMMM, HH:mm');

return [fail(400, 'UNKNOWN_ACTION', 'Невідома дія: ' + ($('Розбір запиту').first().json.action || '(порожньо)'))];

